#hostOpenat(
  dir: bigint,
  namePtr: KernelPointer,
  nameLen: number,
  flags: number,
  mode: number,
): bigint {
  try {
    const name = this.#readComponentFromMemory(namePtr, nameLen);
    const handle = this.io.openat(Number(dir), name, flags, mode);
    // Backends may reuse numeric handles after close. Never let an entry
    // staged for an older iterator leak into a new handle with the same id.
    this.pendingDirectoryEntries.delete(handle);
    return BigInt(handle);
  } catch (e) {
    return BigInt(negErrno(e));
  }
}

#hostFstatat(

/**
 * Open one component relative to a directory handle this host issued.
 *
 * `O_DIRECTORY` yields another anchor; anything else yields a file handle.
 * Both come from the same id space and are released by `close`.
 */
openat(dirHandle: number, name: string, flags: number, mode: number): number {
  const dir = this.getDirHandle(dirHandle);
  const path = joinComponent(dir.path, name);
  const globalHandle = this.nextHandle++;
  if ((flags & OPEN_FLAGS.O_DIRECTORY) !== 0) {
    // Confirm it is a directory before handing back an anchor, so a
    // non-directory component fails here rather than at first use.
    const st = dir.backend.stat(path);
    if ((st.mode & FILE_MODES.S_IFMT) !== FILE_MODES.S_IFDIR) {
      throw new Error(`ENOTDIR: not a directory: ${path}`);
    }
    this.dirHandles.set(globalHandle, {
      backend: dir.backend,
      backendId: dir.backendId,
      path,
      nosuid: dir.nosuid,
      statfs: this.mountStatfs(dir.backend, path, dir.nosuid),
      iterator: null,
    });
    return globalHandle;

fn host_openat(
    &mut self,
    dir: i64,
    name: &[u8],
    flags: u32,
    mode: u32,
) -> Result<i64, Errno> {
    let result =
        unsafe { host_openat(dir, name.as_ptr(), name.len() as u32, flags, mode) };
    checked_host_i64_result(result)
}

};

/// A directory's entries. Each entry gets a getdents cookie when it is
/// created and keeps it until it is removed, so removing entries while a
/// reader walks the directory never shifts the others (POSIX: every entry
/// not removed is returned exactly once), and a listing resumes from its
/// cookie without rebuilding the directory.
#[derive(Default)]
struct DirEntries {
    /// Child inode index and cookie, by name.
    by_name: BTreeMap<Vec<u8>, (u32, u64)>,
    /// Names in creation order, by cookie.
    by_cookie: BTreeMap<u64, Vec<u8>>,
    next_cookie: u64,
